import RAW from './gen/own.json' with { type: 'json' };
import type { I18n, LonLat, Polity, Snapshot, Year } from './types.ts';

/**
 * Our own territory maps (docs/data/territories.md), generated by scripts/build-territories.ts from the seats and
 * holdings in src/shared/data/own/: the phases' metadata and what changed in each, with its source. The geometry is in
 * public/data/atlas/own.json, loaded with the imported shapes. An era with our own maps replaces the imported one.
 */
interface Raw {
  eras: {
    replaces: string;
    phases: { id: string; from: Year; to: Year; title: I18n; note?: I18n; changes: [Year, string, string | null, string | null, string?][]; cites: string[] }[];
    sources: Record<string, I18n>;
    polities: Polity[];
  }[];
  seats: Record<string, { zh: string; en: string; at: LonLat; modern?: string }>;
}
const J = RAW as unknown as Raw;

/** A holding that changed since the previous phase: a seat passing from one polity to another, with the source. */
export interface Change { year: Year; seat: I18n; from: string | null; to: string | null; src?: I18n }

const seatName = (era: string, id: string): I18n => { const s = J.seats[`${era}:${id}`]; return { zh: s?.zh ?? id, en: s?.en ?? id }; };

export const OWN_POLITIES: Polity[] = J.eras.flatMap(e => e.polities);
/** Imported dynasties replaced by our own maps. */
export const OWN_REPLACES: ReadonlySet<string> = new Set(J.eras.map(e => e.replaces));

export const OWN_SNAPSHOTS: Snapshot[] = J.eras.flatMap(e => e.phases.map(p => ({
  id: p.id, scope: 'china' as const, year: p.from, end: p.to, dyn: e.replaces, title: p.title, note: p.note, regions: [], shapes: p.id, own: true,
  cites: (p.cites ?? []).map(k => e.sources[k]).filter(Boolean),
  changes: p.changes.map(([year, seat, from, to, src]): Change => ({
    year, seat: seatName(e.replaces, seat), from, to, src: src ? e.sources[src] : undefined,
  })),
})));

/** The sources behind one of our phases (the holdings it draws, most cited first), for the map's source note. */
export const ownCites = (s: Snapshot, max = 6): I18n[] => (s.cites ?? []).slice(0, max);
